WITH RECURSIVE source_rows AS (
SELECT 'system_events'::text AS table_name, t."event_id"::text AS row_id, to_jsonb(t) AS obj FROM public."system_events" t
UNION ALL
SELECT 'diagnostic_submissions'::text AS table_name, t."id"::text AS row_id, to_jsonb(t) AS obj FROM public."diagnostic_submissions" t
UNION ALL
SELECT 'advisor_prospects'::text AS table_name, t."prospect_id"::text AS row_id, to_jsonb(t) AS obj FROM public."advisor_prospects" t
UNION ALL
SELECT 'health_check_prospects'::text AS table_name, t."prospect_id"::text AS row_id, to_jsonb(t) AS obj FROM public."health_check_prospects" t
UNION ALL
SELECT 'advisor_prospect_activity'::text AS table_name, t."activity_id"::text AS row_id, to_jsonb(t) AS obj FROM public."advisor_prospect_activity" t
UNION ALL
SELECT 'health_check_prospect_activity'::text AS table_name, t."activity_id"::text AS row_id, to_jsonb(t) AS obj FROM public."health_check_prospect_activity" t
), columns(table_name,col,ord) AS (VALUES ('system_events','event_id',0),('system_events','event_type',1),('system_events','status',2),('system_events','submission_id',3),('system_events','public_token',4),('system_events','source',5),('system_events','metadata',6),('system_events','created_at',7),('diagnostic_submissions','id',0),('diagnostic_submissions','created_at',1),('diagnostic_submissions','company_size',2),('diagnostic_submissions','industry',3),('diagnostic_submissions','role',4),('diagnostic_submissions','country_region',5),('diagnostic_submissions','email',6),('diagnostic_submissions','score',7),('diagnostic_submissions','band',8),('diagnostic_submissions','process_clarity_score',9),('diagnostic_submissions','consistency_score',10),('diagnostic_submissions','service_access_score',11),('diagnostic_submissions','ownership_score',12),('diagnostic_submissions','onboarding_score',13),('diagnostic_submissions','technology_alignment_score',14),('diagnostic_submissions','knowledge_self_service_score',15),('diagnostic_submissions','operational_capacity_score',16),('diagnostic_submissions','data_handoffs_score',17),('diagnostic_submissions','change_resilience_score',18),('diagnostic_submissions','answers',19),('diagnostic_submissions','abuse_token',20),('diagnostic_submissions','submission_id',21),('diagnostic_submissions','contact_name',22),('diagnostic_submissions','contact_email',23),('diagnostic_submissions','contact_company',24),('diagnostic_submissions','contact_topic',25),('diagnostic_submissions','contact_message',26),('diagnostic_submissions','contact_source',27),('diagnostic_submissions','advisor_brief',28),('diagnostic_submissions','contact_submitted_at',29),('diagnostic_submissions','status',30),('diagnostic_submissions','last_contacted_at',31),('diagnostic_submissions','notes',32),('diagnostic_submissions','completed_at',33),('diagnostic_submissions','submission_source',34),('diagnostic_submissions','completion_version',35),('diagnostic_submissions','public_token',36),('advisor_prospects','prospect_id',0),('advisor_prospects','name',1),('advisor_prospects','company',2),('advisor_prospects','role',3),('advisor_prospects','source',4),('advisor_prospects','segment',5),('advisor_prospects','diagnostic_status',6),('advisor_prospects','last_contact_date',7),('advisor_prospects','next_action_date',8),('advisor_prospects','observed_signals',9),('advisor_prospects','notes',10),('advisor_prospects','linked_submission_id',11),('advisor_prospects','created_at',12),('advisor_prospects','updated_at',13),('advisor_prospects','relationship_strength',14),('advisor_prospects','deal_stage',15),('advisor_prospects','lead_temperature',16),('advisor_prospects','next_step',17),('advisor_prospects','lost_reason',18),('advisor_prospects','contact_email',19),('advisor_prospects','contact_phone',20),('advisor_prospects','company_website',21),('advisor_prospects','billing_contact_name',22),('advisor_prospects','billing_contact_email',23),('advisor_prospects','linkedin_url',24),('health_check_prospects','prospect_id',0),('health_check_prospects','submission_id',1),('health_check_prospects','name',2),('health_check_prospects','company',3),('health_check_prospects','relationship',4),('health_check_prospects','status',5),('health_check_prospects','last_contact_date',6),('health_check_prospects','next_action_date',7),('health_check_prospects','source',8),('health_check_prospects','notes',9),('health_check_prospects','created_at',10),('health_check_prospects','updated_at',11),('advisor_prospect_activity','activity_id',0),('advisor_prospect_activity','prospect_id',1),('advisor_prospect_activity','linked_submission_id',2),('advisor_prospect_activity','activity_type',3),('advisor_prospect_activity','field_name',4),('advisor_prospect_activity','old_value',5),('advisor_prospect_activity','new_value',6),('advisor_prospect_activity','note',7),('advisor_prospect_activity','changed_by',8),('advisor_prospect_activity','created_at',9),('advisor_prospect_activity','note_type',10),('health_check_prospect_activity','activity_id',0),('health_check_prospect_activity','prospect_id',1),('health_check_prospect_activity','submission_id',2),('health_check_prospect_activity','activity_type',3),('health_check_prospect_activity','field_name',4),('health_check_prospect_activity','old_value',5),('health_check_prospect_activity','new_value',6),('health_check_prospect_activity','note',7),('health_check_prospect_activity','changed_by',8),('health_check_prospect_activity','created_at',9)), cells AS (
SELECT r.table_name,r.row_id,c.col,c.ord,r.obj->c.col AS val FROM source_rows r JOIN columns c USING(table_name)
), inner_tree(table_name,row_id,col,node,path,prefix) AS (
SELECT table_name,row_id,col,CASE WHEN jsonb_typeof(val)='string' THEN (val#>>'{}')::jsonb ELSE val END,ARRAY[]::bigint[],''::text
FROM cells WHERE col IN ('metadata','answers','advisor_brief','observed_signals','segmentation_schema','segmentation_values','responses','response_json','response_data','routes_used') AND val IS NOT NULL AND val<>'null'::jsonb
UNION ALL
SELECT t.table_name,t.row_id,t.col,c.value,t.path||c.ord,
CASE WHEN c.ord>1 THEN ',' ELSE '' END || CASE WHEN jsonb_typeof(t.node)='object' THEN to_json(c.key)::text||':' ELSE '' END
FROM inner_tree t CROSS JOIN LATERAL (
 SELECT key,value,row_number() OVER(ORDER BY CASE WHEN CASE WHEN key ~ '^(0|[1-9][0-9]{0,9})$' THEN key::numeric <= 4294967294 ELSE false END THEN 0 ELSE 1 END, CASE WHEN CASE WHEN key ~ '^(0|[1-9][0-9]{0,9})$' THEN key::numeric <= 4294967294 ELSE false END THEN key::numeric ELSE NULL END, key COLLATE "C")::bigint AS ord FROM jsonb_each(CASE WHEN jsonb_typeof(t.node)='object' THEN t.node ELSE '{}'::jsonb END)
 UNION ALL
 SELECT NULL::text,value,ordinality::bigint AS ord FROM jsonb_array_elements(CASE WHEN jsonb_typeof(t.node)='array' THEN t.node ELSE '[]'::jsonb END) WITH ORDINALITY
) c
), events AS (
SELECT table_name,row_id,col,path,prefix||CASE jsonb_typeof(node) WHEN 'object' THEN '{' WHEN 'array' THEN '[' ELSE CASE WHEN jsonb_typeof(node)='number' THEN regexp_replace(regexp_replace(node::text,'(\.\d*?)0+$','\1'),'\.$','') ELSE node::text END END AS token FROM inner_tree
UNION ALL
SELECT table_name,row_id,col,path||2147483647::bigint,CASE jsonb_typeof(node) WHEN 'object' THEN '}' ELSE ']' END FROM inner_tree WHERE jsonb_typeof(node) IN ('object','array')
), inner_json AS (
SELECT table_name,row_id,col,string_agg(token,'' ORDER BY path) AS canonical FROM events GROUP BY table_name,row_id,col
), canonical_rows AS (
SELECT c.table_name,c.row_id,'{'||string_agg(to_json(c.col)::text||':'||
CASE WHEN i.canonical IS NOT NULL THEN to_json(i.canonical)::text
WHEN c.val IS NULL OR c.val='null'::jsonb THEN 'null'
WHEN c.col ~ '(_at|_until|_expires|_started|_used)$' AND jsonb_typeof(c.val)='string' AND (c.val#>>'{}') ~ '^\d{4}-\d\d-\d\dT' THEN to_json(to_char((c.val#>>'{}')::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))::text
ELSE CASE WHEN jsonb_typeof(c.val)='number' THEN regexp_replace(regexp_replace(c.val::text,'(\.\d*?)0+$','\1'),'\.$','') ELSE c.val::text END END,',' ORDER BY c.ord)||'}' AS canonical
FROM cells c LEFT JOIN inner_json i USING(table_name,row_id,col) GROUP BY c.table_name,c.row_id
)
SELECT n.table_name,count(r.row_id)::integer AS count,encode(extensions.digest(convert_to('['||coalesce(string_agg(r.canonical,',' ORDER BY r.row_id COLLATE "C"),'')||']','UTF8'),'sha256'),'hex') AS hash,now() AS generated_at
FROM (SELECT DISTINCT table_name FROM columns) n LEFT JOIN canonical_rows r USING(table_name) GROUP BY n.table_name ORDER BY n.table_name;
